package vn.tuan.service;
import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.multipart.MultipartFile;import org.springframework.security.crypto.password.PasswordEncoder;import vn.tuan.entity.*;import vn.tuan.repository.*;import java.util.*;import java.math.*;import java.time.*;
@Service @RequiredArgsConstructor public class ConsoleService {
 private final ActorService actors;private final ShopRepository shops;private final ProductRepository products;private final CategoryRepository categories;private final CarrierRepository carriers;private final PromotionRepository promotions;private final AccountRepository accounts;private final OrderRepository orders;private final MediaService media;private final PasswordEncoder passwords;
 public List<Shop> shops(String email){Account a=actors.account(email);return shops.findAll().stream().filter(s->actors.manages(a,s)).toList();}
 public List<Product> products(String email){return shops(email).stream().flatMap(s->products.findByShopOrderByCreatedAtDesc(s).stream()).toList();}
 public List<Order> orders(String email){return shops(email).stream().flatMap(s->orders.findByShopOrderByCreatedAtDesc(s).stream()).sorted(Comparator.comparing(Order::getCreatedAt).reversed()).toList();}
 public List<Account> users(String email){var a=actors.account(email);if("ADMIN".equals(actors.role(a)))return accounts.findAll();return orders(email).stream().map(Order::getAccount).filter(Objects::nonNull).distinct().toList();}
 public List<Promotion> promotions(String email){var a=actors.account(email);return promotions.findAll().stream().filter(p->"ADMIN".equals(actors.role(a)) || p.getShop()!=null && actors.manages(a,p.getShop())).toList();}
 private void admin(String email){OrderRules.require("ADMIN".equals(actors.role(actors.account(email))),"Chỉ Admin thực hiện thao tác toàn hệ thống");}
 @Transactional public void product(String email,Integer id,Integer shopId,Integer categoryId,String name,BigDecimal price,Integer stock,String description,String status,MultipartFile image){Shop shop=actors.shop(email,shopId);OrderRules.require(name!=null && !name.isBlank() && name.length()<=150 && price!=null && price.signum()>0 && price.compareTo(new BigDecimal("10000000"))<=0 && stock!=null && stock>=0,"Tên món, giá hoặc tồn kho không hợp lệ");OrderRules.require(Set.of("ACTIVE","HIDDEN","OUT_OF_STOCK").contains(status),"Trạng thái không hợp lệ");Product p=id==null?new Product():products.lockById(id).orElseThrow();if(id!=null){actors.shop(email,p.getShop().getId());OrderRules.require(p.getShop().getId().equals(shopId),"Không chuyển món đã tạo sang chi nhánh khác");}p.setShop(shop);Category cat=categories.findById(categoryId).orElseThrow();OrderRules.require(cat.getShop()==null || cat.getShop().getId().equals(shopId),"Danh mục không thuộc chi nhánh");p.setCategory(cat);p.setName(name.trim());p.setBasePrice(price);p.setStock(stock);p.setDescription(description);p.setStatus(status);String url=media.upload(image,false);if(url!=null)p.setImageUrl(url);if(p.getImageUrl()==null)p.setImageUrl("/images/tea-placeholder.svg");products.save(p);}
 @Transactional public void hideProduct(String email,Integer id){Product p=products.lockById(id).orElseThrow();actors.shop(email,p.getShop().getId());p.setStatus("HIDDEN");}
 @Transactional public void promotion(String email,Integer id,Integer shopId,String code,int percent,BigDecimal max,BigDecimal min,String type,LocalDateTime expiry,boolean active){var a=actors.account(email);if(shopId!=null)actors.shop(email,shopId);else admin(email);OrderRules.require(code!=null && code.matches("[A-Za-z0-9_-]{3,50}") && percent>0 && percent<=100 && max!=null && max.signum()>=0 && min!=null && min.signum()>=0 && Set.of("PRODUCT","SHIPPING").contains(type),"Mã, mức giảm hoặc điều kiện không hợp lệ");Promotion p=id==null?new Promotion():promotions.findById(id).orElseThrow();if(id!=null){if(p.getShop()==null)admin(email);else actors.shop(email,p.getShop().getId());}p.setCode(code.toUpperCase(Locale.ROOT));p.setShop(shopId==null?null:shops.findById(shopId).orElseThrow());p.setDiscountPercent(percent);p.setMaxDiscount(max);p.setMinOrderAmount(min);p.setType(type);p.setExpiresAt(expiry);p.setIsActive(active);promotions.save(p);}
 @Transactional public void category(String email,Integer id,Integer shopId,String name){if(shopId==null)admin(email);else {OrderRules.require(!"VENDOR".equals(actors.role(actors.account(email))),"Chỉ Manager hoặc Admin quản lý danh mục");actors.shop(email,shopId);}OrderRules.require(name!=null && !name.isBlank() && name.length()<=100,"Tên danh mục không hợp lệ");Category c=id==null?new Category():categories.findById(id).orElseThrow();if(id!=null){if(c.getShop()==null)admin(email);else actors.shop(email,c.getShop().getId());}c.setShop(shopId==null?null:shops.findById(shopId).orElseThrow());c.setName(name.trim());categories.save(c);}
 @Transactional public void carrier(String email,Integer id,Integer shopId,String name,BigDecimal fee,boolean active){if(shopId==null)admin(email);else {OrderRules.require(!"VENDOR".equals(actors.role(actors.account(email))),"Chỉ Manager hoặc Admin quản lý vận chuyển");actors.shop(email,shopId);}OrderRules.require(name!=null && !name.isBlank() && name.length()<=100 && fee!=null && fee.signum()>=0,"Thông tin nhà vận chuyển không hợp lệ");Carrier c=id==null?new Carrier():carriers.findById(id).orElseThrow();if(id!=null){if(c.getShop()==null)admin(email);else actors.shop(email,c.getShop().getId());}c.setShop(shopId==null?null:shops.findById(shopId).orElseThrow());c.setName(name);c.setCarrierName(name);c.setBaseFee(fee);c.setIsActive(active);carriers.save(c);}
 @Transactional public void shop(String email,Integer id,String name,String description,MultipartFile logo){Shop s=actors.shop(email,id);OrderRules.require(name!=null && !name.isBlank() && name.length()<=150,"Tên cửa hàng không hợp lệ");s.setShopName(name);s.setDescription(description);String url=media.upload(logo,false);if(url!=null)s.setLogoUrl(url);}
 @Transactional public void assignManager(String email,Integer shopId,Integer managerId,BigDecimal commission){admin(email);Shop s=shops.findById(shopId).orElseThrow();Account m=managerId==null?null:accounts.findById(managerId).orElseThrow();OrderRules.require(m==null || "MANAGER".equals(actors.role(m)),"Tài khoản phải có vai trò Manager");OrderRules.require(commission!=null && commission.signum()>=0 && commission.compareTo(new BigDecimal("100"))<=0,"Chiết khấu từ 0 đến 100%");s.setManager(m);s.setCommissionPercent(commission);}
 @Transactional public void manager(String email,String managerEmail,String password){admin(email);OrderRules.require(managerEmail!=null && managerEmail.matches("[^ @]+@[^ @]+[.][^ @]+") && password!=null && password.length()>=8 && password.length()<=72,"Email hoặc mật khẩu không hợp lệ");OrderRules.require(!accounts.existsByEmail(managerEmail),"Email đã tồn tại");accounts.save(Account.builder().email(managerEmail.trim().toLowerCase(Locale.ROOT)).password(passwords.encode(password)).role("MANAGER").isActive(true).emailVerified(true).build());}
 public List<Category> categories(String email){var a=actors.account(email);return categories.findAll().stream().filter(c->c.getShop()==null || actors.manages(a,c.getShop())).toList();}
 public List<Carrier> carriers(String email){var a=actors.account(email);return carriers.findAll().stream().filter(c->c.getShop()==null || actors.manages(a,c.getShop())).toList();}
 public List<Account> managers(){return accounts.findByRoleAndIsActiveOrderByCreatedAtDesc("MANAGER",true);}
}
